using System.Collections.Frozen;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.Text.Json;
using System.Text.Json.Serialization;
using Anthropic.Core;
using Anthropic.Exceptions;

namespace Anthropic.Models.Files;

/// <summary>
/// The file has `downloadable: false`. Only files generated by a tool, such as the
/// code execution tool, can be downloaded.
/// </summary>
[JsonConverter(
    typeof(JsonModelConverter<
        FileNotDownloadableErrorDetails,
        FileNotDownloadableErrorDetailsFromRaw
    >)
)]
public sealed record class FileNotDownloadableErrorDetails : JsonModel
{
    public JsonElement ErrorCode
    {
        get
        {
            this._rawData.Freeze();
            return this._rawData.GetNotNullStruct<JsonElement>("error_code");
        }
        init { this._rawData.Set("error_code", value); }
    }

    /// <inheritdoc/>
    public override void Validate()
    {
        if (
            !JsonElement.DeepEquals(
                this.ErrorCode,
                JsonSerializer.SerializeToElement("file_not_downloadable")
            )
        )
        {
            throw new AnthropicInvalidDataException("Invalid value given for constant");
        }
    }

    public FileNotDownloadableErrorDetails()
    {
        this.ErrorCode = JsonSerializer.SerializeToElement("file_not_downloadable");
    }

#pragma warning disable CS8618
    [SetsRequiredMembers]
    public FileNotDownloadableErrorDetails(
        FileNotDownloadableErrorDetails fileNotDownloadableErrorDetails
    )
        : base(fileNotDownloadableErrorDetails) { }
#pragma warning restore CS8618

    public FileNotDownloadableErrorDetails(IReadOnlyDictionary<string, JsonElement> rawData)
    {
        this._rawData = new(rawData);

        this.ErrorCode = JsonSerializer.SerializeToElement("file_not_downloadable");
    }

#pragma warning disable CS8618
    [SetsRequiredMembers]
    FileNotDownloadableErrorDetails(FrozenDictionary<string, JsonElement> rawData)
    {
        this._rawData = new(rawData);
    }
#pragma warning restore CS8618

    /// <inheritdoc cref="FileNotDownloadableErrorDetailsFromRaw.FromRawUnchecked"/>
    public static FileNotDownloadableErrorDetails FromRawUnchecked(
        IReadOnlyDictionary<string, JsonElement> rawData
    )
    {
        return new(FrozenDictionary.ToFrozenDictionary(rawData));
    }
}

class FileNotDownloadableErrorDetailsFromRaw : IFromRawJson<FileNotDownloadableErrorDetails>
{
    /// <inheritdoc/>
    public FileNotDownloadableErrorDetails FromRawUnchecked(
        IReadOnlyDictionary<string, JsonElement> rawData
    ) => FileNotDownloadableErrorDetails.FromRawUnchecked(rawData);
}
